// A, R1, R2 y B, como en el laboratorio. Cada router decide solo con su propia tabla.
const aInt = ip => ip.split(".").reduce((n, o) => n * 256 + Number(o), 0);
function contiene(prefijo, ip) {
  const [red, largo] = prefijo.split("/");
  const bits = Number(largo);
  const mascara = bits === 0 ? 0 : (0xFFFFFFFF << (32 - bits)) >>> 0;
  return ((aInt(ip) & mascara) >>> 0) === ((aInt(red) & mascara) >>> 0);
}

const tablas = {
  R1: [["192.0.2.0/24", "directo"], ["198.51.100.0/24", "directo"], ["203.0.113.0/24", "R2"]],
  R2: [["192.0.2.0/24", "R1"], ["198.51.100.0/24", "directo"], ["203.0.113.0/24", "directo"]],
};
const hosts = { "192.0.2.10": "A", "203.0.113.10": "B" };

function enviar(destino, ttl, primero) {
  console.log(`A manda un paquete a ${destino} con TTL ${ttl}`);
  let actual = primero;
  for (let paso = 1; paso <= 70; paso++) {
    ttl -= 1;                                           // cada router resta 1
    if (ttl === 0) { console.log(`  ${actual}: TTL llegó a 0, descarta y avisa «tiempo excedido» a A`); return; }
    const candidatas = tablas[actual].filter(([p]) => contiene(p, destino));
    if (candidatas.length === 0) { console.log(`  ${actual}: sin ruta, descarta`); return; }
    candidatas.sort((x, y) => Number(y[0].split("/")[1]) - Number(x[0].split("/")[1]));
    const [prefijo, siguiente] = candidatas[0];          // el prefijo más largo gana
    if (siguiente === "directo") {
      console.log(`  ${actual}: TTL ${ttl}, ruta ${prefijo} directa -> entrega a ${hosts[destino] ?? "nadie"}`);
      return;
    }
    console.log(`  ${actual}: TTL ${ttl}, ruta ${prefijo} -> reenvía a ${siguiente}`);
    actual = siguiente;
  }
}

enviar("203.0.113.10", 64, "R1");
console.log("--- ahora R1 y R2 tienen una ruta por defecto que apunta el uno al otro ---");
tablas.R1.push(["0.0.0.0/0", "R2"]);
tablas.R2.push(["0.0.0.0/0", "R1"]);
enviar("10.9.9.9", 8, "R1");
